    format: 'SoloKnownNonBrowserProcessWitnessV1',
    scope: `Exact root kernel ${row.argv} executable only; ownership and unreadable resource/tag fields remain unknown; no signal authority.`,
    process: {
      pid: row.pid,
      ppid: row.ppid,
      pgid: row.pgid,
      birth: row.birth,
      identityKind: row.identityKind,
      parentUniqueId: row.parentUniqueId,
      version: row.version,
      euid: row.euid,
      ruid: row.ruid,
      state: row.state,
      executable: row.argv,
