      pid: row.pid,
      ppid: row.ppid,
      pgid: row.pgid,
      birth: row.birth,
      identityKind: row.identityKind,
      version: row.version,
      euid: row.euid,
      ruid: row.ruid,
      parentUniqueId: row.parentUniqueId,
      state: row.state,
