  };
  const bytes = Buffer.byteLength(JSON.stringify(next, null, 2).replace(/^/gm, ' '.repeat(24)));
  record.firstAmbiguousIdentityFollowup =
    bytes <= next.maximumBytes
      ? next
      : {
          format: next.format,
          status: 'overflow',
          reason: 'byte-cap',
          maximumBytes: next.maximumBytes,
          minimumSerializationBytes: bytes,
          firstChange: null,
          last: null,
        };
