export function collectUnattributedProcesses(
  all,
  before,
  owned,
  leaderPid,
  record,
  darwin = false,
  retainInventories = false,
) {
  if (darwin && retainInventories === 'identity-maps-v2')
    retainAmbiguousIdentityFollowup(all, record);
  const ambiguous = [];
  for (const row of all.values()) {
    if (
      !live(row) ||
      !(browserCommand(row) || row.inspectionIncomplete) ||
      same(before.get(row.pid), row) ||
      same(owned.get(row.pid), row)
