      continue;
    const witness = darwin
      ? (darwinForeignSystemProcessWitness(row, before, all, owned, leaderPid) ??
        darwinKnownNonBrowserProcessWitness(row, before, all, owned, leaderPid))
      : null;
    if (!witness) {
      ambiguous.push(row);
      continue;
    }
    assert(Array.isArray(record.foreignSystemProcesses), 'Foreign process witness owner');
    const encoded = JSON.stringify(witness);
    if (!record.foreignSystemProcesses.some((w) => JSON.stringify(w) === encoded)) {
      if (record.foreignSystemProcesses.length >= 64 || Buffer.byteLength(encoded) > 2048) {
        record.foreignSystemProcessOverflow = true;
        ambiguous.push(row);
      } else record.foreignSystemProcesses.push(witness);
    }
  }
  // Cleanup resamples the live inventory. Keep its first unattributed row
  // separately so a later empty sample cannot erase the reason for failure.
  // This is bounded evidence only, never ownership or signal authority.
  if (ambiguous.length && !record.firstAmbiguousInventory) {
    if (darwin && retainInventories)
      record.firstAmbiguousIdentityMaps = ambiguityIdentityMaps(
        before,
        all,
        owned,
        leaderPid,
        retainInventories === 'identity-maps-v2',
      );
    const row = ambiguous[0],
      argv = row.argv ?? '';
    record.firstAmbiguousInventory = {
      format: 'SoloFirstAmbiguousInventoryV1',
      ambiguousCount: ambiguous.length,
      retainedCount: 1,
      additionalRowsOmitted: ambiguous.length - 1,
      row: {
        pid: row.pid,
        ppid: row.ppid,
        pgid: row.pgid,
        birth: row.birth,
        state: row.state,
        rss: row.rss,
        argv: argv.slice(0, 1024),
        argvCodeUnits: argv.length,
        argvTruncated: argv.length > 1024,
        ownerTagged: row.ownerTagged,
        inspectionIncomplete: row.inspectionIncomplete,
        identityKind: row.identityKind,
        euid: row.euid,
        ruid: row.ruid,
        parentUniqueId: row.parentUniqueId,
        version: row.version,
        pathInspection: row.pathInspection,
        rssInspection: row.rssInspection,
        ownerTagInspection: row.ownerTagInspection,
