test('prepared context rejects before evaluation for invalid configuration and bounds a hung RPC', async () => {
  let calls = 0;
  const page = {
    evaluate: () => {
      calls++;
      return new Promise(() => {});
    },
  };
  assert.throws(() =>
    requestedMeasurementContext({
      mode: 'persistent',
      headless: true,
      viewport: { width: Infinity, height: 2 },
    }),
  );
  await assert.rejects(
    capturePreparedMeasurementContext(page, { mode: 'unknown', headless: true }),
  );
  assert.equal(calls, 0);
  await assert.rejects(
    capturePreparedMeasurementContext(
      page,
      { mode: 'ephemeral', headless: true },
      { timeoutMs: 10 },
    ),
    /exceeded deadline/,
  );
  assert.equal(calls, 1, 'no retries or continued RPC after the stage deadline');
});

test('prospective call sites collect provenance in setup or preparation, never in an active loop', async () => {
  const observer = await readFile(
    new URL('./observe-solo-performance.mjs', import.meta.url),
    'utf8',
  );
  const qualifier = await readFile(new URL('./qualify-solo-runtime.mjs', import.meta.url), 'utf8');
  const hosted = await readFile(
    new URL('./run-solo-remote-correctness.mjs', import.meta.url),
    'utf8',
  );
  assert.equal(
    (observer.match(/measurementContext = await capturePreparedMeasurementContext/g) ?? []).length,
    1,
  );
  assert.equal(
    (
      qualifier.match(
        /report\.environment\.measurementContext = await capturePreparedMeasurementContext/g,
      ) ?? []
    ).length,
    1,
  );
  assert.match(hosted, /installedRuntimeCandidates: await captureWebKitRuntimeFiles\(/);
  assert(
    observer.indexOf('measurementContext = await capturePreparedMeasurementContext') <
      observer.indexOf('await page.evaluate(() => window.soloTimingProbe.startWorkProbe())'),
  );
  assert(
    observer.indexOf('measurementContext = await capturePreparedMeasurementContext') <
      observer.indexOf("page.locator('#shell-featured').click()"),
  );
  assert(
    qualifier.indexOf(
      'report.environment.measurementContext = await capturePreparedMeasurementContext',
    ) < qualifier.indexOf("await prepareObservation('initial-ready')"),
  );
  assert.match(qualifier, /if \(journalCostOptions\) \{\s*report\.environment\.measurementContext/);
  assert.match(hosted, /engine === 'webkit' && extension === 'diagnostics'/);
  assert(
    hosted.indexOf('installedRuntimeCandidates:') <
      hosted.indexOf('const outer = await downloadCandidate'),
  );
});

